from pathlib import Path
import hashlib
import json

roots = [Path('products/services'), Path('products/distribution')]
scopes = ('invoice', 'text-csv', 'open-software-tender', 'welfare-tender')
markers = ('baseline', 'checkpoint', 'retire', 'expiry', 'operator-card')
for root in roots:
    if not root.is_dir():
        continue
    for path in sorted(root.rglob('*')):
        if not path.is_file() or path.suffix not in {'.json', '.md'}:
            continue
        name = path.as_posix().lower()
        if not any(scope in name for scope in scopes) or not any(marker in name for marker in markers):
            continue
        raw = path.read_bytes()
        record = {'path': path.as_posix(), 'sha256': hashlib.sha256(raw).hexdigest()}
        if path.suffix == '.json' and len(raw) <= 32768:
            try:
                data = json.loads(raw)
            except ValueError:
                data = None
            if isinstance(data, dict):
                record['fields'] = {key: value for key, value in data.items() if isinstance(value, (str, int, bool)) and any(term in key.lower() for term in ('deadline', 'retire', 'expiry', 'window', 'verdict', 'digest', 'status'))}
        print(json.dumps(record, ensure_ascii=True))
